UPDATE public.spots SET access = '{"shore": true, "parking": "Several car parks off SH1, at the end of Koura Street, and at the Tongariro National Trout Centre", "walkIn": "Angler access tracks lead off the Tongariro River Trail; some end abruptly at the river edge", "facilities": ["Formed river trail", "Swing bridges to both banks", "Tongariro National Trout Centre"], "notes": "Access is well developed, with a maintained track network and swing bridges serving both sides of the river. The stretch between the SH1 road bridge and Red Hut pool attracts heavy angling pressure year-round.", "sourceUrl": "https://www.doc.govt.nz/parks-and-recreation/places-to-go/central-north-island/places/turangi-area/things-to-do/tongariro-river-trail/"}'::jsonb, updated_at = now() WHERE slug = 'tongariro-river';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Ennis Fishing Access Site boat ramp, just south of Ennis on the Madison", "parking": "Gravel and grass parking at the access site, with room for trailers", "facilities": ["Boat ramp", "Vault toilets", "Drinking water", "Campground", "Picnic tables", "Fire rings"], "notes": "Montana''s Fishing Access Site network provides public entry along the river. Camping at Ennis FAS is limited to 7 days for a small fee, and sites suit RVs up to about 25 feet. Popular access points fill early on summer weekends, particularly during the salmonfly hatch.", "sourceUrl": "https://myfwp.mt.gov/fwpPub/landsMgmt/search.action"}'::jsonb, updated_at = now() WHERE slug = 'madison-river-montana';
